// ============================================================================
//  SRO Asset Studio - core/I18nLangs.h
//
//  The UI string tables for every language beyond the original TR / EN / AR.
//  Split out of I18n.h purely for size: the scheme is identical - the key is
//  the TURKISH source literal, exactly as it appears in the code, and a missing
//  entry falls through to that source rather than disappearing.
//
//  Included from the middle of I18n.h, inside namespace sro::i18n_detail, so
//  `Table` is already declared. Do NOT include this file directly.
//
//  Keeping the three long placeholder strings byte-identical to the source
//  matters: they are looked up by full text, so a single changed space or a
//  \r\n turned into \n silently drops the translation.
// ============================================================================
#pragma once

